var o=`0292-njeguski-steak`;var n=`world-0292`;var r=`ME`;var a=`southern-europe`;var i=4;var s=61;var d={en:`Njeguški Steak`,ua:`Негуський стейк`};var l={en:`A traditional Montenegro dish made with pork loin, smoked ham, cheddar cheese, all-purpose flour. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Чорногорія. Основні інгредієнти: свиняча корейка, копчена шинка, сир чедер, пшеничне борошно універсальне. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`pork-loin`,700,`g`],[`smoked-ham`,190,`g`],[`cheddar-cheese`,170,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:8,i:[[`all-purpose-flour`,85,`g`],[`chicken-egg`,2,`pcs`],[`breadcrumbs`,150,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,110,`ml`]]}];var h={slug:o,id:n,country:`ME`,region:a,servings:4,minutes:61,title:d,text:l,steps:u};export{r as country,h as default,n as id,s as minutes,a as region,i as servings,o as slug,u as steps,l as text,d as title};